/** A straight wall defined by its centerline on a level. */
export interface Wall {
  base_offset_m?: number;
  end: any[];
  height_m: number;
  id: string;
  kind: WallKind;
  left_material_id?: string | null;
  level_id: string;
  material_id?: string | null;
  right_material_id?: string | null;
  start: any[];
  thickness_m: number;
}

export type WallKind = "exterior" | "interior" | "retaining" | "parapet";

export interface WithinEnvelopeRule {
  kind?: string;
}

export type WorkflowState = "NEW_PROJECT" | "SITE_INGESTION" | "SITE_NEEDS_VERIFICATION" | "SITE_APPROVED" | "INTERVIEWING" | "PROGRAM_REVIEW" | "PROGRAM_APPROVED" | "CONCEPT_GENERATION" | "CONCEPT_REVIEW" | "PLAN_APPROVED" | "BLENDER_BUILD" | "BLENDER_REVIEW" | "MODEL_APPROVED" | "UNREAL_BUILD" | "UNREAL_REVIEW";

export interface Zone {
  id: string;
  name: string;
  privacy: Privacy;
  space_ids?: string[];
}

export interface AgentRoster {
  roles: AgentRole[];
}

export interface Approval {
  approved_at: string;
  approved_by: Actor;
  artifact: ArtifactRef;
  conditions?: string[];
  gate: Gate;
  id: string;
  statement: string;
}

/** assumptions.yaml */
export interface AssumptionsFile {
  assumptions?: Assumption[];
  project_id: string;
  provenance: Provenance;
  schema_version?: string;
}

export interface BenchmarkFixture {
  cases?: BenchmarkCase[];
  description: string;
  expectations: ExpectedFinding[];
  generator: string;
  ground_truth: string;
  id: string;
  program: SpaceProgram;
  schema_version?: string;
  site: Site;
}

export interface BuildRecord {
  id: string;
  input_plan: ArtifactRef;
  outputs?: BuildOutput[];
  provenance: Provenance;
  schema_version?: string;
  script?: string | null;
  target: BuildTarget;
  tool: string;
  tool_version?: string | null;
}

export interface CodePack {
  authority: string;
  edition: string;
  effective_date: string;
  id: string;
  jurisdiction: string;
  rule_ids: string[];
  rules?: CodeRule[];
  schema_version?: string;
  source: string;
  verification_status?: CodePackVerification;
  verified_at?: string | null;
  verified_by?: Actor | null;
}

export interface ConstraintSet {
  constraints?: Constraint[];
  id: string;
  project_id: string;
  provenance: Provenance;
  schema_version?: string;
}

export interface DesignBrief {
  budget?: Money | null;
  contradictions?: Contradiction[];
  facts?: BriefFact[];
  household?: HouseholdMember[];
  id: string;
  interview_rounds_completed?: number;
  project_id: string;
  provenance: Provenance;
  schema_version?: string;
  target_gross_area_m2?: number | null;
}

export interface EvaluationReport {
  compliance: ComplianceStatement;
  evaluators: EvaluatorRun[];
  id: string;
  metrics?: MetricClaim[];
  plan_ref: ArtifactRef;
  provenance: Provenance;
  schema_version?: string;
  violations?: Violation[];
}

export interface InterviewSession {
  brief_id?: string;
  id: string;
  pending_attempts?: number;
  pending_question_id?: string | null;
  project_id: string;
  provenance: Provenance;
  schema_version?: string;
  site?: SiteContext | null;
  status?: SessionStatus;
  turns?: InterviewTurn[];
}

/** open_questions.yaml */
export interface OpenQuestionsFile {
  project_id: string;
  provenance: Provenance;
  questions?: OpenQuestion[];
  schema_version?: string;
}

/** Everything the owner said that is not an interview answer, oldest first. */
export interface OwnerStatementsFile {
  project_id: string;
  provenance: Provenance;
  schema_version?: string;
  statements?: OwnerStatement[];
}

/** One immutable version of a plan option. Stored under artifact id = option_id. */
export interface PlanVersion {
  change_request?: ChangeRequest | null;
  generation?: GenerationRecord | null;
  label: string;
  model: HouseModel;
  option_id: string;
  parent?: ArtifactRef | null;
  provenance: Provenance;
  schema_version?: string;
  strategy?: string | null;
}

/** project.json: identity only. Workflow state is replayed from events.jsonl. */
export interface ProjectManifest {
  classification: DataClassification;
  created_at: string;
  created_by: Actor;
  description?: string | null;
  id: string;
  name: string;
  schema_version?: string;
}

/** File exchanged between the reviewer UI and house-ai plan revise. */
export interface RevisionOpsFile {
  author: string;
  comments?: RevisionComment[];
  created_at?: string;
  operations?: RevisionOp[];
  option: string;
  plan_version: number;
  project: string;
  schema_version?: string;
  verbatim_request: string;
}

/** What changed between two plan versions, reported after every revision. */
export interface RevisionReport {
  area_changes?: AreaChange[];
  assumptions?: string[];
  from_version: ArtifactRef;
  geometry_changed?: string[];
  id: string;
  metric_changes?: MetricChange[];
  new_violations?: string[];
  provenance: Provenance;
  requested_change: string;
  resolved_violations?: string[];
  rooms_added?: string[];
  rooms_changed?: string[];
  rooms_removed?: string[];
  schema_version?: string;
  to_version: ArtifactRef;
}

/** scene_manifest.json transferring an approved Blender build to Unreal Engine. */
export interface SceneManifest {
  blender_build_ref: ArtifactRef;
  cameras?: SceneCamera[];
  coordinate_system_id: string;
  epsg?: number | null;
  id: string;
  lights?: SceneLight[];
  materials?: SceneMaterial[];
  objects?: SceneObject[];
  origin_grid_m?: any[] | null;
  plan_ref: ArtifactRef;
  player_start?: Transform3D | null;
  provenance: Provenance;
  schema_version?: string;
  units?: LengthUnit;
}

/** An original input file, preserved byte-for-byte under source/. */
export interface SourceDocument {
  classification: DataClassification;
  id: string;
  imported_at: string;
  imported_by: Actor;
  media_type?: string | null;
  original_filename: string;
  sha256: string;
  size_bytes: number;
  stored_path: string;
}

/** One line of events.jsonl. ``hash`` chains each event to the previous one. */
export interface WorkflowEvent {
  actor: Actor;
  at: string;
  from_state?: WorkflowState | null;
  hash: string;
  payload?: Record<string, any>;
  prev_hash?: string | null;
  reason?: string | null;
  seq: number;
  to_state?: WorkflowState | null;
  type: EventType;
}

/** Gate approval command and status */
export interface GateApprovalInfo {
  name: string;
  approved: boolean;
  approved_at?: string | null;
  approved_by?: string | null;
  artifact?: ArtifactRef | null;
  approve_command: string;
  confirm_command?: string;
  description: string;
}

/** One plan option entry inside the reviewer bundle */
export interface ReviewerPlanEntry {
  option_id: string;
  label: string;
  strategy?: string | null;
  version?: number | null;
  is_exploratory: boolean;
  exploratory_warning?: string;
  plan: PlanVersion;
  plan_ref?: ArtifactRef;
  evaluation?: EvaluationReport | null;
  revision?: RevisionReport | null;
  svg?: string | null;
}

/** Top-level bundle JSON structure exported by house-ai reviewer export */
export interface ReviewerBundle {
  schema_version: string;
  project: {
    name: string;
    state: string;
    manifest?: ProjectManifest | null;
  };
  gates: Record<string, GateApprovalInfo>;
  site?: Site | null;
  program?: SpaceProgram | null;
  brief?: DesignBrief | null;
  plans: ReviewerPlanEntry[];
  comparison_markdown?: string;
}
